use std :: time :: Duration ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Humanizes a number to a readable format with B/M/k suffixes."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `n` - The number to humanize"] # [doc = ""] # [doc = " # Examples"] # [doc = " ```ignore"] # [doc = " assert_eq!(humanize_number(1500), \"1.5k\");"] # [doc = " assert_eq!(humanize_number(1500000), \"1.5M\");"] # [doc = " assert_eq!(humanize_number(1500000000), \"1.5B\");"] # [doc = " assert_eq!(humanize_number(500), \"500\");"] # [doc = " ```"] pub fn humanize_number (n : usize) -> String { match n { n if n >= 1_000_000_000 => format ! ("{:.1}B" , n as f64 / 1_000_000_000.0) , n if n >= 1_000_000 => format ! ("{:.1}M" , n as f64 / 1_000_000.0) , n if n >= 1_000 => format ! ("{:.1}k" , n as f64 / 1_000.0) , _ => n . to_string () , } }